CREATE TABLE sbl_digital_twin_skill_imports (id char(36) NOT NULL, twin_id char(36) NOT NULL, owner_user_id char(36) NOT NULL, source_type varchar(32) NOT NULL, source_name varchar(255) NOT NULL, source_url varchar(2048) NULL, relative_path varchar(512) NULL, content_hash varchar(64) NOT NULL, content longtext NOT NULL, parsed json NOT NULL, status varchar(16) NOT NULL DEFAULT '待学习', error_message text NULL, skill_id char(36) NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY uq_twin_skill_import_hash (twin_id, content_hash), KEY idx_twin_skill_import_twin (twin_id, status, created_at), CONSTRAINT fk_twin_skill_import_twin FOREIGN KEY (twin_id) REFERENCES sbl_digital_twins(id) ON DELETE CASCADE, CONSTRAINT fk_twin_skill_import_owner FOREIGN KEY (owner_user_id) REFERENCES sbl_users(id) ON DELETE CASCADE, CONSTRAINT fk_twin_skill_import_skill FOREIGN KEY (skill_id) REFERENCES sbl_digital_twin_skills(id) ON DELETE SET NULL);
